"""Public-seam coverage for legacy Excel staff imports."""

from __future__ import annotations

import base64
from types import SimpleNamespace

import pytest

from app.modules.users.staff_import_service import _split_full_name, _xls_cell_text, parse_upload

LEGACY_STAFF_XLS = base64.b64decode(
    ""
)


def test_legacy_xls_sections_become_canonical_branch_departments():
    parsed = parse_upload("legacy-staff.xls", LEGACY_STAFF_XLS)

    assert parsed.sheet_name == "Лист1"
    assert parsed.header_row == 2
    assert parsed.invalid_rows == []
    assert len(parsed.rows) == 4
    assert [row.personnel_number for row in parsed.rows] == ["0001", "0002", "0003", "0004"]
    assert [row.department for row in parsed.rows] == [
        "Филиал Петропавловск",
        "Филиал Петропавловск",
        "Филиал Павлодар",
        "Филиал Павлодар",
    ]
    assert [(row.last_name, row.first_name) for row in parsed.rows] == [
        ("Иванов", "Иван Иванович"),
        ("Петрова", "Анна Сергеевна"),
        ("Сидоров", "Петр Петрович"),
        ("Ким", "Мария Олеговна"),
    ]


def test_invalid_legacy_xls_has_a_safe_user_facing_error():
    with pytest.raises(ValueError, match="Не удалось прочитать старый Excel-файл"):
        parse_upload("broken.xls", b"not-an-excel-workbook")


def test_full_name_preserves_patronymic_without_a_dedicated_model_field():
    assert _split_full_name("Иванов Иван Иванович") == ("Иван Иванович", "Иванов")


def test_numeric_personnel_number_preserves_legacy_zero_mask():
    book = SimpleNamespace(
        xf_list=[SimpleNamespace(format_key=17)],
        format_map={17: SimpleNamespace(format_str="0000")},
    )
    cell = SimpleNamespace(ctype=2, value=1.0, xf_index=0)

    assert _xls_cell_text(book, cell) == "0001"
